import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.Cyu1VozZ.js";const g=JSON.parse('{"title":"Charts & Pivot Tables","description":"","frontmatter":{},"headers":[],"relativePath":"sheets/charts.md","filePath":"sheets/charts.md"}'),s={name:"sheets/charts.md"};function i(l,t,n,h,d,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="charts-pivot-tables" tabindex="-1">Charts &amp; Pivot Tables <a class="header-anchor" href="#charts-pivot-tables" aria-label="Permalink to &quot;Charts &amp; Pivot Tables&quot;">​</a></h1><p>Wafflebase includes built-in charts and pivot tables so you can visualize and summarize your data without leaving the spreadsheet.</p><h2 id="charts" tabindex="-1">Charts <a class="header-anchor" href="#charts" aria-label="Permalink to &quot;Charts&quot;">​</a></h2><h3 id="insert-a-chart" tabindex="-1">Insert a Chart <a class="header-anchor" href="#insert-a-chart" aria-label="Permalink to &quot;Insert a Chart&quot;">​</a></h3><ol><li>Select the data range you want to chart (include headers in the first row). The selection must cover at least 2 rows and 2 columns</li><li>Click the <strong>Insert chart</strong> button (the bar-chart icon) in the toolbar. On a narrow screen the toolbar collapses its extra tools into a <strong>More formatting options</strong> (⋮) menu — open it and choose <strong>Insert chart</strong> there</li><li>A bar chart appears anchored to the top-left cell of your selection, with the chart editor panel open on the right</li></ol><h3 id="chart-types" tabindex="-1">Chart Types <a class="header-anchor" href="#chart-types" aria-label="Permalink to &quot;Chart Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Best For</th></tr></thead><tbody><tr><td><strong>Bar</strong></td><td>Comparing categories side by side</td></tr><tr><td><strong>Line</strong></td><td>Showing trends over time</td></tr><tr><td><strong>Area</strong></td><td>Trends with volume emphasis</td></tr><tr><td><strong>Pie</strong></td><td>Showing proportions of a whole</td></tr><tr><td><strong>Scatter</strong></td><td>Visualizing relationships between two numeric values</td></tr></tbody></table><h3 id="configure-your-chart" tabindex="-1">Configure Your Chart <a class="header-anchor" href="#configure-your-chart" aria-label="Permalink to &quot;Configure Your Chart&quot;">​</a></h3><p>The chart editor panel has two tabs:</p><p><strong>Setup</strong> — Choose the chart type, data range, X-axis column, and which columns to plot as series. A pie chart plots a single <strong>value column</strong> rather than multiple series.</p><p><strong>Customize</strong> — Set the chart title, legend position (Top, Bottom, Right, Left, or None), toggle gridlines, and pick a color palette.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The available controls depend on the chart type. Pie charts have no gridlines, so the <strong>Show gridlines</strong> checkbox is not shown for them.</p></div><h3 id="move-and-resize" tabindex="-1">Move and Resize <a class="header-anchor" href="#move-and-resize" aria-label="Permalink to &quot;Move and Resize&quot;">​</a></h3><p>Drag the chart to reposition it on the sheet. Drag the edges or corners to resize.</p><h3 id="color-palettes" tabindex="-1">Color Palettes <a class="header-anchor" href="#color-palettes" aria-label="Permalink to &quot;Color Palettes&quot;">​</a></h3><p>Three built-in palettes are available:</p><ul><li><strong>Theme (default)</strong> — Adapts to light/dark theme</li><li><strong>Warm</strong> — Orange and earth tones</li><li><strong>Cool</strong> — Blue and teal tones</li></ul><h3 id="charts-follow-their-source-data" tabindex="-1">Charts Follow Their Source Data <a class="header-anchor" href="#charts-follow-their-source-data" aria-label="Permalink to &quot;Charts Follow Their Source Data&quot;">​</a></h3><p>A chart reads its source range every time it draws, so edits to the source cells show up in the chart right away. Pivot tables work the other way — see <a href="#refresh">Refresh</a> below.</p><h2 id="pivot-tables" tabindex="-1">Pivot Tables <a class="header-anchor" href="#pivot-tables" aria-label="Permalink to &quot;Pivot Tables&quot;">​</a></h2><p>Pivot tables let you summarize large datasets by grouping and aggregating values — similar to Google Sheets pivot tables.</p><h3 id="create-a-pivot-table" tabindex="-1">Create a Pivot Table <a class="header-anchor" href="#create-a-pivot-table" aria-label="Permalink to &quot;Create a Pivot Table&quot;">​</a></h3><ol><li>Select a data range (first row must be headers, at least 2 rows)</li><li>Right-click the selection and choose <strong>Insert pivot table</strong></li><li>A new <strong>Pivot Table</strong> tab is created and the pivot editor panel opens on the right</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Insert pivot table is only on the right-click menu — there is no toolbar button for it.</p></div><h3 id="configure-fields" tabindex="-1">Configure Fields <a class="header-anchor" href="#configure-fields" aria-label="Permalink to &quot;Configure Fields&quot;">​</a></h3><p>The pivot editor panel has a section per area. Click <strong>Add</strong> in a section and pick a source column from the dropdown; there is no drag-and-drop. Each field shows a <strong>✕</strong> button to remove it again.</p><ul><li><strong>Rows</strong> — Group data by these columns (supports multi-level grouping)</li><li><strong>Columns</strong> — Create column headers from field values</li><li><strong>Values</strong> — Aggregated data; choose SUM, COUNT, COUNTA, AVERAGE, MIN, or MAX per field</li><li><strong>Filters</strong> — Add a source column here to reserve it for filtering</li></ul><p>Row and column fields each carry a sort toggle for ascending / descending order.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The <strong>Filters</strong> area currently has no way to choose which values to hide, so a filter field does not change the pivot result yet. Filter your source data before pivoting it if you need a subset.</p></div><h3 id="refresh" tabindex="-1">Refresh <a class="header-anchor" href="#refresh" aria-label="Permalink to &quot;Refresh&quot;">​</a></h3><p>Pivot tables materialize their result into the cells of the pivot tab, so they do not update when the source data changes. Click <strong>Refresh pivot table</strong> at the bottom of the editor panel to recalculate.</p><h3 id="grand-totals" tabindex="-1">Grand Totals <a class="header-anchor" href="#grand-totals" aria-label="Permalink to &quot;Grand Totals&quot;">​</a></h3><p>Row and column grand totals are shown by default. Clear <strong>Show row totals</strong> or <strong>Show column totals</strong> in the editor panel&#39;s <strong>Totals</strong> section if you don&#39;t need them.</p>',33)])])}const p=e(s,[["render",i]]);export{g as __pageData,p as default};
